// Dates and business-day calendars, checked against known facts and against
// QuantLib day by day (fixtures generated by scripts/quantlib_reference.py).
#include <gtest/gtest.h>

#include <map>
#include <set>

#include "mcb/core/calendar.hpp"
#include "mcb/core/date.hpp"
#include "test_util.hpp"

using namespace mcb;

TEST(Date, RoundTripsEveryDayOverFourCenturies) {
  Date d(1900, 1, 1);
  int prevSerial = d.serial() - 1;
  for (; d <= Date(2300, 12, 31); d = d.addDays(1)) {
    const auto c = d.ymd();
    ASSERT_EQ(Date(c.year, c.month, c.day), d);
    ASSERT_EQ(d.serial(), prevSerial + 1);
    prevSerial = d.serial();
  }
}

TEST(Date, KnownWeekdaysAndLeapYears) {
  EXPECT_EQ(Date(1970, 1, 1).weekday(), Weekday::Thu);
  EXPECT_EQ(Date(2012, 12, 11).weekday(), Weekday::Tue);
  EXPECT_EQ(Date(2026, 11, 13).weekday(), Weekday::Fri);
  EXPECT_EQ(Date(2000, 2, 29).weekday(), Weekday::Tue);
  EXPECT_TRUE(Date::isLeap(2000));
  EXPECT_FALSE(Date::isLeap(1900));
  EXPECT_TRUE(Date::isLeap(2024));
  EXPECT_FALSE(Date::isLeap(2026));
  EXPECT_EQ(Date(2024, 12, 31).dayOfYear(), 366);
  EXPECT_EQ(Date(2026, 3, 1).dayOfYear(), 60);
}

TEST(Date, MonthArithmeticClipsToMonthEnd) {
  EXPECT_EQ(Date(2026, 1, 31).addMonths(1), Date(2026, 2, 28));
  EXPECT_EQ(Date(2024, 1, 31).addMonths(1), Date(2024, 2, 29));
  EXPECT_EQ(Date(2026, 3, 31).addMonths(-1), Date(2026, 2, 28));
  EXPECT_EQ(Date(2024, 2, 29).addYears(1), Date(2025, 2, 28));
  EXPECT_EQ(Date(2026, 11, 17).addMonths(18), Date(2028, 5, 17));
  EXPECT_EQ(Date(2026, 11, 17).addMonths(-23), Date(2024, 12, 17));
  EXPECT_EQ(Date(2026, 2, 10).endOfMonth(), Date(2026, 2, 28));
  EXPECT_TRUE(Date(2026, 4, 30).isEndOfMonth());
  EXPECT_FALSE(Date(2026, 4, 29).isEndOfMonth());
}

TEST(Date, ParsesTheFormatsUsedByTheDataSources) {
  EXPECT_EQ(Date::parse("2026-11-13"), Date(2026, 11, 13));   // ISO (ECB, MOEX, GSW)
  EXPECT_EQ(Date::parse("11/13/2026"), Date(2026, 11, 13));   // US (Treasury, Eris)
  EXPECT_EQ(Date::parse("1/5/2026"), Date(2026, 1, 5));
  EXPECT_EQ(Date::parse("20261113"), Date(2026, 11, 13));
  EXPECT_EQ(Date::parse("13.11.2026"), Date(2026, 11, 13));   // Russian style
  EXPECT_EQ(Date(2026, 1, 5).iso(), "2026-01-05");
  Date d;
  EXPECT_FALSE(Date::tryParse("2026-13-01", d));
  EXPECT_FALSE(Date::tryParse("2026-02-30", d));
  EXPECT_FALSE(Date::tryParse("hello", d));
  EXPECT_FALSE(Date::tryParse("", d));
  EXPECT_THROW(Date::parse("31/12/2026"), Error);
  EXPECT_TRUE(Date().isNull());
}

TEST(Period, ParsesTenors) {
  EXPECT_EQ(Period::parse("3M"), (Period{3, TimeUnit::Months}));
  EXPECT_EQ(Period::parse("10y"), (Period{10, TimeUnit::Years}));
  EXPECT_EQ(Period::parse("1W"), (Period{1, TimeUnit::Weeks}));
  EXPECT_EQ(Period::parse(" 2D "), (Period{2, TimeUnit::Days}));
  EXPECT_EQ(Period::parse("18M").str(), "18M");
  EXPECT_THROW(Period::parse("M"), Error);
  EXPECT_THROW(Period::parse("3X"), Error);
  EXPECT_NEAR(Period::parse("18M").approxYears(), 1.5, 1e-12);
}

TEST(Calendar, EasterAndImmDates) {
  // Easter Monday: 2026-04-06, 2027-03-29, 2000-04-24, 2038-04-26 (latest possible)
  EXPECT_EQ(easterMondayDayOfYear(2026), Date(2026, 4, 6).dayOfYear());
  EXPECT_EQ(easterMondayDayOfYear(2027), Date(2027, 3, 29).dayOfYear());
  EXPECT_EQ(easterMondayDayOfYear(2000), Date(2000, 4, 24).dayOfYear());
  EXPECT_EQ(easterMondayDayOfYear(2038), Date(2038, 4, 26).dayOfYear());
  EXPECT_EQ(immDate(2012, 12), Date(2012, 12, 19));
  EXPECT_EQ(immDate(2013, 3), Date(2013, 3, 20));
  EXPECT_EQ(immDate(2026, 12), Date(2026, 12, 16));
  EXPECT_EQ(nextImmDate(Date(2012, 12, 11)), Date(2012, 12, 19));
  EXPECT_EQ(nextImmDate(Date(2012, 12, 19)), Date(2013, 3, 20));
  EXPECT_EQ(nextImmDate(Date(2026, 12, 20)), Date(2027, 3, 17));
}

TEST(Calendar, KnownHolidays) {
  const Calendar target(Calendar::Kind::Target), sofr(Calendar::Kind::UsSofr), gov(Calendar::Kind::UsGovernmentBond);
  EXPECT_TRUE(target.isHoliday(Date(2026, 12, 25)));
  EXPECT_TRUE(target.isHoliday(Date(2026, 4, 3)));    // Good Friday
  EXPECT_TRUE(target.isHoliday(Date(2026, 5, 1)));
  EXPECT_TRUE(target.isBusinessDay(Date(2026, 11, 26)));  // Thanksgiving is not a TARGET holiday
  EXPECT_TRUE(sofr.isHoliday(Date(2026, 11, 26)));        // Thanksgiving
  EXPECT_TRUE(sofr.isHoliday(Date(2027, 1, 18)));         // Martin Luther King Day
  EXPECT_TRUE(sofr.isHoliday(Date(2026, 6, 19)));         // Juneteenth
  EXPECT_TRUE(sofr.isHoliday(Date(2026, 11, 11)));        // Veterans Day
  // Good Friday 2026 falls on the first Friday of April (employment report):
  // the bond market is open, but SOFR is not published.
  EXPECT_TRUE(gov.isBusinessDay(Date(2026, 4, 3)));
  EXPECT_TRUE(sofr.isHoliday(Date(2026, 4, 3)));
}

TEST(Calendar, AdjustAndAdvance) {
  const Calendar target(Calendar::Kind::Target), sofr(Calendar::Kind::UsSofr);
  using C = BusinessDayConvention;
  // Saturday 2026-10-31: following crosses the month end, modified following rolls back.
  EXPECT_EQ(target.adjust(Date(2026, 10, 31), C::Following), Date(2026, 11, 2));
  EXPECT_EQ(target.adjust(Date(2026, 10, 31), C::ModifiedFollowing), Date(2026, 10, 30));
  EXPECT_EQ(target.adjust(Date(2026, 10, 31), C::Unadjusted), Date(2026, 10, 31));
  EXPECT_EQ(target.adjust(Date(2026, 11, 1), C::Preceding), Date(2026, 10, 30));
  EXPECT_EQ(target.adjust(Date(2026, 11, 1), C::ModifiedPreceding), Date(2026, 11, 2));
  // T+2 spot from Friday 2026-11-13 is Tuesday the 17th; the EUR snapshot date 2012-12-11 gives the 13th.
  EXPECT_EQ(sofr.advance(Date(2026, 11, 13), 2, TimeUnit::Days), Date(2026, 11, 17));
  EXPECT_EQ(target.advance(Date(2012, 12, 11), 2, TimeUnit::Days), Date(2012, 12, 13));
  EXPECT_EQ(sofr.advance(Date(2026, 11, 17), -2, TimeUnit::Days), Date(2026, 11, 13));
  // Thanksgiving week: 2 business days after Wed 2026-11-25 is Mon 2026-11-30.
  EXPECT_EQ(sofr.advance(Date(2026, 11, 25), 2, TimeUnit::Days), Date(2026, 11, 30));
  // End-of-month rule: last business day maps to last business day.
  EXPECT_EQ(target.advance(Date(2026, 2, 27), 1, TimeUnit::Months, C::ModifiedFollowing, true), Date(2026, 3, 31));
  EXPECT_EQ(target.advance(Date(2026, 2, 27), 1, TimeUnit::Months, C::ModifiedFollowing, false), Date(2026, 3, 27));
  EXPECT_TRUE(target.isEndOfMonth(Date(2026, 10, 30)));
  EXPECT_EQ(target.endOfMonth(Date(2026, 10, 5)), Date(2026, 10, 30));
  EXPECT_EQ(target.businessDaysBetween(Date(2026, 11, 13), Date(2026, 11, 17)), 2);
}

TEST(Calendar, CustomHolidays) {
  Calendar cal(Calendar::Kind::WeekendsOnly);
  EXPECT_TRUE(cal.isBusinessDay(Date(2026, 11, 18)));
  cal.addHoliday(Date(2026, 11, 18));
  EXPECT_TRUE(cal.isHoliday(Date(2026, 11, 18)));
  EXPECT_EQ(cal.adjust(Date(2026, 11, 18)), Date(2026, 11, 19));
}

TEST(CalendarVsQuantLib, HolidayListsMatchDayByDay1990To2080) {
  const auto table = readCsvFile(mcbtest::dataPath("ql/calendar_holidays.csv"));
  std::map<std::string, std::set<Date>> expected;
  for (const auto& row : table.rows) expected[row[0]].insert(Date::parse(row[1]));
  ASSERT_EQ(expected.size(), 4u);
  for (const auto& [name, holidays] : expected) {
    const Calendar cal = mcbtest::calendarByName(name);
    int mismatches = 0;
    for (Date d(1990, 1, 1); d <= Date(2080, 12, 31); d = d.addDays(1)) {
      if (d.isWeekend()) {
        ASSERT_TRUE(cal.isHoliday(d));
        continue;
      }
      const bool ours = cal.isHoliday(d), theirs = holidays.count(d) > 0;
      if (ours != theirs) {
        ++mismatches;
        ADD_FAILURE() << name << " " << d.iso() << ": mcb holiday=" << ours << " QuantLib=" << theirs;
        if (mismatches > 10) break;
      }
    }
    EXPECT_EQ(mismatches, 0) << name;
  }
}

TEST(CalendarVsQuantLib, AdvanceMatchesOnRandomCases) {
  const auto t = readCsvFile(mcbtest::dataPath("ql/calendar_advance.csv"));
  ASSERT_GT(t.rows.size(), 1000u);
  int failures = 0;
  for (std::size_t i = 0; i < t.rows.size() && failures < 10; ++i) {
    const Calendar cal = mcbtest::calendarByName(t.at(i, "calendar"));
    const Date d = Date::parse(t.at(i, "date"));
    const Period p = Period::parse(t.at(i, "n") + t.at(i, "unit"));
    const auto conv = mcbtest::conventionByName(t.at(i, "convention"));
    const bool eom = t.at(i, "eom") == "1";
    const Date got = cal.advance(d, p, conv, eom);
    if (got != Date::parse(t.at(i, "result"))) {
      ++failures;
      ADD_FAILURE() << t.at(i, "calendar") << " advance(" << d.iso() << ", " << p.str() << ", " << t.at(i, "convention")
                    << ", eom=" << eom << ") = " << got.iso() << " but QuantLib gives " << t.at(i, "result");
    }
  }
  EXPECT_EQ(failures, 0);
}
